UPDATE SETTINGS SET EXT_ID = 'blockNotificationSchedulerHtml', `DESC` = null, REALM_ID = 'user', NAME = 'Сообщение от scheduler о блокировке', UNIT = null, TYPE = 'MESSAGE', VALUE = '<p>Ваша учетная запись для входа в Личный кабинет «Дом.ру Бизнес» <font color="red">заблокирована</font>. Доступ к услугам при этом не блокируется.</p><p> Вы не использовали свою учетную запись в течении длительного времени. Чтобы восстановить доступ к учетной записи, обратитесь к своему персональному менеджеру или оставьте заявку в чате <a class="no_block" href="https://newlkb2b.dom.ru">Личного кабинета</a>, или по телефону <br> <a class="no_block" href="tel:88003339000">8 800 333 9000</a>.</p>' WHERE ID = '087fe2f4-5a67-11ec-bf63-0242ac130002';
UPDATE SETTINGS SET EXT_ID = 'emailEnabledAccountBodyHtml', `DESC` = null, REALM_ID = 'user', NAME = 'Сообщение о блокировке', UNIT = null, TYPE = 'MESSAGE', VALUE = '<p>Ваша учетная запись для входа в <a class="no_block" href="https://newlkb2b.dom.ru">Личный кабинет</a> «Дом.ру Бизнес» <font color="green">разблокирована</font>.</p>' WHERE ID = '148727c4-15a0-4fca-92f2-d53aaf1868df';
UPDATE SETTINGS SET EXT_ID = 'blockPrepareNotificationSchedulerHtml', `DESC` = null, REALM_ID = 'user', NAME = 'Сообщение от scheduler предупреждении о блокировке', UNIT = null, TYPE = 'MESSAGE', VALUE = '<p>Ваша учетная запись для входа в Личный кабинет «Дом.ру Бизнес» <font color="red">будет заблокирована через %s</font>.</p><p>Для предотвращения блокировки учетной записи, просим Вас войти в <a class="no_block" href="%s">Личный кабинет</a> до истечения указанного срока.</p>' WHERE ID = '174d9ccc-5a67-11ec-bf63-0242ac130002';
UPDATE SETTINGS SET EXT_ID = 'emailVerificationLoginBodyHtml', `DESC` = null, REALM_ID = 'user', NAME = 'Сообщение о подтверждение УЗ', UNIT = null, TYPE = 'MESSAGE', VALUE = '<p>Подтвердите Вашу учетную запись для входа в Личный кабинет «Дом.ру Бизнес» по ссылке.Срок действия ссылки {4}.</p><p class = "block_link"><a href="{0}">Подтвердить учетную запись</a></p>' WHERE ID = '17d329be-985d-49ab-a75c-0377448b3eb7';
UPDATE SETTINGS SET EXT_ID = 'passwordExpiresSchedulerHtml', `DESC` = null, REALM_ID = 'user', NAME = 'Сообщение от scheduler о истечении срока пароля', UNIT = null, TYPE = 'MESSAGE', VALUE = '<p>Срок действия пароля от учетной записи для входа в Личный кабинет «Дом.ру Бизнес» истёк. Для восстановления пароля Вам необходимо перейти по <a class="no_block" href="%s">ссылке</a> и воспользоваться функцией «Забыли пароль?»</p>' WHERE ID = '1a4b398e-5a67-11ec-bf63-0242ac130002';
UPDATE SETTINGS SET EXT_ID = 'identityProviderLinkBodyHtml', `DESC` = null, REALM_ID = 'user', NAME = 'Сообщение о связывании УЗ', UNIT = null, TYPE = 'MESSAGE', VALUE = '<p>Был создан запрос на связь Вашей учетной записи <a class="no_block" href="mailto:{1}">{1}</a> с учетной записью пользователя {2} {0}. После объединения учетных записей Вы можете войти в Личный кабинет «Дом.ру Бизнес» <a class="no_block" href="mailto:{1}">{1}</a> через {0}. Если это были Вы, пройдите по ссылке, чтобы связать учетные записи.</p><p class = "block_link"><a href="{3}">Связать учетные данные</a></p><p class="small_text">Эта ссылка устареет через 24 часа.</p><p class="small_text">Если Вы не хотите объединять учетные записи, проигнорируйте это письмо.</p>' WHERE ID = '2bcb24f5-6168-4809-ac79-a681c08e33e9';
UPDATE SETTINGS SET EXT_ID = 'emailVerificationAuthBodyHtml', `DESC` = null, REALM_ID = 'user', NAME = 'Сообщение о подтверждении УЗ', UNIT = null, TYPE = 'MESSAGE', VALUE = '<p>Код для подтверждения данных Вашей учетной записи Личного кабинета «Дом.ру Бизнес»:</p><p class = "text_bolid margin_block">{0}</p>' WHERE ID = '2c03c1ab-b921-416f-ba16-4f4ba0024ce7';
UPDATE SETTINGS SET EXT_ID = 'emailCredentialDisableBodyHtml', `DESC` = null, REALM_ID = 'user', NAME = 'Сообщение о сбросе пароля', UNIT = null, TYPE = 'MESSAGE', VALUE = '<p>Чтобы защитить Ваши персональные данные, пароль к учетной записи для входа в Личный кабинет «Дом.ру Бизнес» был сброшен. Чтобы активировать учетную запись перейдите по ссылке <a href="{0}">«Восстановление пароля»</a> и смените его.</p>' WHERE ID = '4311bdd8-b4e0-472e-82cb-604b74a99951';
UPDATE SETTINGS SET EXT_ID = 'emailDisabledAccountBodyHtml', `DESC` = null, REALM_ID = 'user', NAME = 'Сообщение о блокировке УЗ', UNIT = null, TYPE = 'MESSAGE', VALUE = '<p>Ваша учетная запись для входа в Личный кабинет «Дом.ру Бизнес» <font color="red">заблокирована</font>. Доступ к услугам при этом не блокируется.</p> <p>Чтобы восстановить доступ к учетной записи, обратитесь к своему персональному менеджеру или оставьте заявку в чате <a class="no_block" href="https://newlkb2b.dom.ru">Личного кабинета</a>, или по телефону <a class="no_block" href="tel:88003339000">8 800 333 9000</a>.</p>' WHERE ID = '4a3df31f-27de-447b-95cd-1768d4efe263';
UPDATE SETTINGS SET EXT_ID = 'emailAccountDataBodyHtml', `DESC` = null, REALM_ID = 'user', NAME = 'Сообщение о создании УЗ', UNIT = null, TYPE = 'MESSAGE', VALUE = '<p>Для Вас создана учетная запись для входа в Личный кабинет «Дом.ру Бизнес».</p>' WHERE ID = '743e43aa-d84c-48cc-a3c2-9f874fde4532';
UPDATE SETTINGS SET EXT_ID = 'emailAccountCreateBodyHtml', `DESC` = null, REALM_ID = 'user', NAME = 'Сообщение о создании УЗ', UNIT = null, TYPE = 'MESSAGE', VALUE = '<p>Для Вас создана учетная запись для входа в Личный кабинет «Дом.ру Бизнес».</p>' WHERE ID = '9f558134-412b-11ec-973a-0242ac130003';
UPDATE SETTINGS SET EXT_ID = 'GratitudeUp', `DESC` = null, REALM_ID = 'user', NAME = 'Благодарность внизу сообщения', UNIT = null, TYPE = 'MESSAGE', VALUE = 'С уважением, Дом.ру Бизнес!' WHERE ID = 'f3c33a96-c9bd-46bf-9f32-6617314585d5';
UPDATE SETTINGS SET EXT_ID = 'executeActionsBodyHtml', `DESC` = null, REALM_ID = 'user', NAME = 'Сообщение от администратора для обновления данных', UNIT = null, TYPE = 'MESSAGE', VALUE = '<p>Администратор «Дом.ру Бизнес» просит обновить Вас данные учетной записи <a class="no_block" href="mailto:{2}">{2}</a>. Пройдите по ссылке</p><p><a class="no_block" href="{0}">Обновить данные</a>,</p><p>чтобы начать этот процесс.</p><p>Эта ссылка устареет через {5}.</p>' WHERE ID = 'fb0d728d-2e50-4556-9e6e-c8d787225496';

